import{_ as t,c as s,o as i,j as e,a as r}from"./chunks/framework.Dnh4IO1K.js";const f=JSON.parse('{"title":"卷一·28","description":"易小帖 - 卷一·28","frontmatter":{"title":"卷一·28","description":"易小帖 - 卷一·28"},"headers":[],"relativePath":"zh/classics/yixiaotie/028.md","filePath":"zh/classics/yixiaotie/028.md"}'),o={name:"zh/classics/yixiaotie/028.md"};function c(n,a,l,d,p,m){return i(),s("div",null,[...a[0]||(a[0]=[e("h1",{id:"卷一·28",tabindex:"-1"},[r("卷一·28 "),e("a",{class:"header-anchor",href:"#卷一·28","aria-label":"Permalink to “卷一·28”"},"​")],-1),e("p",null,"豐其沛，沛者水草之名。《公羊傳》草棘曰沛，《禮記‧王制》註有草所生曰萊，水所生曰沛。語應劭雲：沛者草木之蔽茂，齊侯田於沛是也。自王輔嗣註作幡幔，而字書遂有以斾通沛者。然終是改字，非舊義矣。若虞仲翔註易，有曰「日蔽雲中稱蔀，日在雲下稱沛」，則不知所據。且一在雲中，一在雲下，何所分別。漢人有師承，或非杜撰，然何以謾誕乃爾。",-1)])])}const h=t(o,[["render",c]]);export{f as __pageData,h as default};
